S_IPAC = "Sources: Principles of Transmission of Microorganisms (AlMutawa), Introduction to Infection Control (Payne), Nicole's Notes pp. 131, 139 to 140"
S_OUT = "Sources: Important Terms and Outbreak Management (Summers), Nicole's Notes pp. 135 to 138"

import math  # noqa: E402


def _chain():
    links = ["Infectious agent", "Reservoir", "Portal of exit", "Mode of transmission", "Portal of entry", "Susceptible host"]
    cx, cy, R = 320, 185, 140
    o = ['<svg viewBox="0 0 640 370" xmlns="http://www.w3.org/2000/svg"><style>.t{font-size:19px;font-weight:700;fill:var(--ink)}.m{font-size:17px;fill:var(--muted)}</style>',
         '<defs><marker id="ah" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="var(--c)"/></marker></defs>']
    pts = [(cx + R * 1.5 * math.cos(math.radians(-90 + i * 60)), cy + R * math.sin(math.radians(-90 + i * 60))) for i in range(6)]
    for i in range(6):
        x1, y1 = pts[i]; x2, y2 = pts[(i + 1) % 6]
        f = .30
        o.append(f'<line x1="{x1+(x2-x1)*f:.0f}" y1="{y1+(y2-y1)*f:.0f}" x2="{x1+(x2-x1)*(1-f):.0f}" y2="{y1+(y2-y1)*(1-f):.0f}" stroke="var(--c)" stroke-width="3" marker-end="url(#ah)"/>')
    for (x, y), l in zip(pts, links):
        o.append(f'<rect x="{x-102:.0f}" y="{y-22:.0f}" width="204" height="44" rx="22" fill="var(--cbg)" stroke="var(--c)" stroke-width="2"/><text x="{x:.0f}" y="{y+6:.0f}" text-anchor="middle" class="t">{l}</text>')
    o.append(f'<text x="{cx}" y="{cy-4}" text-anchor="middle" class="m">Break any link</text><text x="{cx}" y="{cy+20}" text-anchor="middle" class="m">to stop infection</text></svg>')
    return "".join(o)


def _curves():
    sets = [("Point source", [0, 1, 4, 9, 7, 4, 2, 1, 0, 0, 0, 0, 0, 0]),
            ("Continuous source", [0, 1, 3, 5, 6, 6, 7, 6, 6, 5, 3, 1, 0, 0]),
            ("Intermittent source", [0, 4, 6, 2, 0, 0, 3, 6, 3, 0, 0, 5, 4, 1]),
            ("Propagated", [1, 2, 1, 0, 2, 4, 3, 1, 4, 7, 5, 2, 6, 8])]
    o = ['<svg viewBox="0 0 640 400" xmlns="http://www.w3.org/2000/svg"><style>.h{font-size:20px;font-weight:700;fill:var(--ink)}.ax{stroke:var(--faint);stroke-width:2}</style>']
    for k, (name, ys) in enumerate(sets):
        ox, oy = (k % 2) * 325 + 10, (k // 2) * 200 + 10
        o.append(f'<text x="{ox}" y="{oy+20}" class="h">{name}</text>')
        base = oy + 175
        o.append(f'<line x1="{ox}" y1="{base}" x2="{ox+300}" y2="{base}" class="ax"/>')
        for i, y in enumerate(ys):
            h = y * 15
            o.append(f'<rect x="{ox+4+i*21}" y="{base-h}" width="17" height="{h}" fill="var(--c)" opacity=".8"/>')
    o.append("</svg>")
    return "".join(o)


